68	/// A PeerHandle is a specially designated reference to the peer
69	/// which removes the peer from the device when dropped.
70	///
71	/// A PeerHandle cannot be cloned (unlike the wrapped type).
72	/// A PeerHandle dereferences to a Peer (meaning you can use it like a Peer struct)
73	pub struct PeerHandle<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> {
