215	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> PeerInner<E, C, T, B> {
216	    /// Send a raw message to the peer (used for handshake messages)
217	    ///
218	    /// # Arguments
219	    ///
220	    /// - `msg`, message body to send to peer
221	    ///
222	    /// # Returns
223	    ///
224	    /// Unit if packet was sent, or an error indicating why sending failed
225	    pub fn send_raw(&self, msg: &[u8]) -> Result<(), RouterError> {
226	        // send to endpoint (if known)
227	        match self.endpoint.lock().as_mut() {
228	            Some(endpoint) => {
229	                let outbound = self.device.outbound.read();
230	                if outbound.0 {
231	                    outbound
232	                        .1
233	                        .as_ref()
234	                        .ok_or(RouterError::SendError)
235	                        .and_then(|w| w.write(msg, endpoint).map_err(|_| RouterError::SendError))
236	                } else {
237	                    Ok(())
238	                }
239	            }
240	            None => Err(RouterError::NoEndpoint),
241	        }
242	    }
243	}
244	
245	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> Peer<E, C, T, B> {
246	    /// Encrypt and send a message to the peer
247	    ///
248	    /// Arguments:
249	    ///
250	    /// - `msg` : A padded vector holding the message (allows in-place construction of the transport header)
251	    /// - `stage`: Should the message be staged if no key is available
252	    pub(super) fn send(&self, msg: Vec<u8>, stage: bool) {
253	        // check if key available
254	        let (job, need_key) = {
255	            let mut enc_key = self.enc_key.lock();
256	            match enc_key.as_mut() {
257	                None => {
258	                    log::debug!("no key encryption key available");
259	                    if stage {
260	                        self.staged_packets.lock().push_back(msg);
261	                    };
262	                    (None, true)
263	                }
264	                Some(mut state) => {
265	                    // avoid integer overflow in nonce
266	                    if state.nonce >= REJECT_AFTER_MESSAGES - 1 {
267	                        log::debug!("encryption key expired");
268	                        *enc_key = None;
269	                        if stage {
270	                            self.staged_packets.lock().push_back(msg);
271	                        }
272	                        (None, true)
273	                    } else {
