34	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> ReceiveJob<E, C, T, B> {
35	    pub fn new(
36	        buffer: Vec<u8>,
37	        state: Arc<DecryptionState<E, C, T, B>>,
38	        endpoint: E,
39	    ) -> ReceiveJob<E, C, T, B> {
40	        ReceiveJob(Arc::new(Inner {
41	            ready: AtomicBool::new(false),
42	            buffer: Mutex::new((Some(endpoint), buffer)),
43	            state,
44	        }))
45	    }
46	}
