48	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> ParallelJob
49	    for ReceiveJob<E, C, T, B>
50	{
51	    fn queue(&self) -> &Queue<Self> {
52	        &self.0.state.peer.inbound
53	    }
54	
55	    /* The parallel section of an incoming job:
56	     *
57	     * - Decryption.
58	     * - Crypto-key routing lookup.
59	     *
60	     * Note: We truncate the message buffer to 0 bytes in case of authentication failure
61	     * or crypto-key routing failure (attempted impersonation).
62	     *
63	     * Note: We cannot do replay protection in the parallel job,
64	     * since this can cause dropping of packets (leaving the window) due to scheduling.
65	     */
66	    fn parallel_work(&self) {
67	        debug_assert_eq!(
68	            self.is_ready(),
69	            false,
70	            "doing parallel work on completed job"
71	        );
72	        log::trace!("processing parallel receive job");
73	
74	        // decrypt
75	        {
76	            // closure for locking
77	            let job = &self.0;
78	            let peer = &job.state.peer;
79	            let mut msg = job.buffer.lock();
80	
81	            // process buffer
82	            let ok = (|| {
83	                // cast to header followed by payload
84	                let (header, packet): (LayoutVerified<&mut [u8], TransportHeader>, &mut [u8]) =
85	                    match LayoutVerified::new_from_prefix(&mut msg.1[..]) {
86	                        Some(v) => v,
87	                        None => return false,
88	                    };
89	
90	                // create nonce object
91	                let mut nonce = [0u8; 12];
92	                debug_assert_eq!(nonce.len(), CHACHA20_POLY1305.nonce_len());
93	                nonce[4..].copy_from_slice(header.f_counter.as_bytes());
94	                let nonce = Nonce::assume_unique_for_key(nonce);
